// Generated by `guardkit init`; edits are overwritten on the next run.
import { atom, read, update } from 'claude-code'
import type { Register } from 'claude-code'

import type { FormView } from '../types'

const PYTHON = '__GUARDKIT_PYTHON__'
const SOURCE = '__GUARDKIT_SOURCE__'
const STORE = `import sys; sys.path.insert(0, ${JSON.stringify(SOURCE)}); from guardkit.safe_input import store_main; raise SystemExit(store_main(sys.argv[1:]))`
const PANE = 'guardkit-input'
const TOOL = 'mcp__guardkit-input__open_safe_input'
const STATUS_TOOL = 'mcp__guardkit-input__safe_input_status'
const NAME = /^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$/
const DOT = '•'
const IDLE: FormView = { phase: 'idle', name: '', kind: 'token', service: '', lengths: [], message: '', outcome: 'none' }

const view = atom({ plugin: 'guardkit-input', key: 'view' } as const, IDLE, { shape: 'view-2' })

type Outcome = 'stored' | 'cancelled' | 'failed' | 'expired'

// Typed values live only here: never in $.state, the view atom, a log or a result.
let values: string[] = []
let finish: ((outcome: Outcome) => void) | undefined

function wipe() {
  values = values.map(() => '')
  values = []
}

async function end($: any, outcome: Outcome, message: string) {
  wipe()
  const done = finish
  finish = undefined
  await update($, view, v => ({ ...v, phase: 'done', lengths: [], message, outcome }))
  done?.(outcome)
}

async function begin($: any, name: string, kind: 'token' | 'login', service: string): Promise<Outcome> {
  if (finish) return 'failed'
  if (!NAME.test(name)) return 'failed'
  values = kind === 'login' ? ['', ''] : ['']
  const outcome = new Promise<Outcome>(resolve => {
    finish = resolve
  })
  await update($, view, () => ({
    phase: 'entry', name, kind, service, lengths: values.map(() => 0), message: '', outcome: 'none',
  }))
  await $.ui.open({ id: PANE, title: 'Safe input', focus: true, closeOnEscape: true })
  void $.clock.after(300_000, () => {
    if (finish) void end($, 'expired', 'Timed out. Nothing was stored.')
  })
  return outcome
}

async function edit($: any, index: number, text: string) {
  const shown = DOT.repeat(values[index].length)
  let next: string
  if (text.startsWith(shown)) next = values[index] + text.slice(shown.length)
  else if (shown.startsWith(text)) next = values[index].slice(0, text.length)
  else next = text.split(DOT).join('')
  values[index] = next
  await update($, view, v => ({ ...v, lengths: values.map(x => x.length) }))
}

async function submit($: any, index: number) {
  if (values.every(Boolean)) return save($)
  const count = values.length
  const order = Array.from({ length: count }, (_, step) => (index + 1 + step) % count)
  const target = order.find(i => !values[i])
  if (target !== undefined) await $.ui.focus({ requestId: PANE, key: `f${target}` })
}

async function save($: any) {
  const v = await read($, view)
  if (v.phase !== 'entry' || !values.every(Boolean)) {
    await update($, view, x => ({ ...x, message: 'Fill in every field first.' }))
    return
  }
  const payload = v.kind === 'token' ? values[0] : JSON.stringify({ username: values[0], password: values[1] })
  const ran = await $.process.run([PYTHON, '-E', '-c', STORE, v.name, v.kind], { stdin: payload, cwd: '/', timeoutMs: 20_000 })
  if (ran.exitCode === 0) await end($, 'stored', `Stored as "${v.name}". The agent only gets the reference.`)
  else await update($, view, x => ({ ...x, message: 'Could not save. Check the OS secret store.' }))
}


export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({ name: 'safe-input', description: 'Enter a token or login privately: /safe-input NAME [token|login] [SERVICE]' })
    await $.tool.register({
      name: 'open_safe_input',
      description: 'Ask the user to enter a token or login in a private masked pane. Values go straight to the OS keystore. Returns at once with status awaiting_user; poll safe_input_status for the outcome. Returns only status and credential_ref. Never ask for credentials in chat.',
      inputSchema: {
        type: 'object',
        properties: {
          name: { type: 'string', description: 'Non-secret reference name, e.g. github-token' },
          kind: { type: 'string', enum: ['token', 'login'] },
          service: { type: 'string', description: 'Service label shown to the user' },
        },
        required: ['name'],
      },
      isDeferred: false,
    })
    await $.tool.register({
      name: 'safe_input_status',
      description: 'Status of the last open_safe_input request: awaiting_user, stored, cancelled, failed, expired or none. Never returns values.',
      isDeferred: false,
    })
    return next(e)
  })

  on('command.run', { command: 'safe-input' }, async ($, e) => {
    const [name = '', kind = 'token', ...rest] = e.args.trim().split(/\s+/)
    if (!NAME.test(name) || (kind !== 'token' && kind !== 'login')) {
      return { text: 'Usage: /safe-input NAME [token|login] [SERVICE]' }
    }
    void begin($, name, kind, rest.join(' ') || name)
    return { text: 'Safe input pane opened.' }
  })

  on('tool.call', { tool: TOOL }, async ($, e: any) => {
    const name = String(e.name ?? '')
    const kind = e.kind === 'login' ? 'login' : 'token'
    const service = String(e.service ?? name).slice(0, 128)
    if (!NAME.test(name) || finish) return { result: JSON.stringify({ status: 'failed', credential_ref: name, kind }) }
    void begin($, name, kind, service)
    return { result: JSON.stringify({ status: 'awaiting_user', credential_ref: name, kind }) }
  })

  on('tool.call', { tool: STATUS_TOOL }, async $ => {
    const v = await read($, view)
    const status = v.phase === 'entry' ? 'awaiting_user' : v.phase === 'done' ? v.outcome : 'none'
    return { result: JSON.stringify({ status, credential_ref: v.name }) }
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { Box, Text, Button, Input } = $.ui.resolve(e)
    const v = await read($, view)
    if (v.phase !== 'entry') {
      return (
        <Box flexDirection="column">
          <Text>{v.message || 'No input requested.'}</Text>
          <Button key="close" onPress={() => void $.ui.close({ id: PANE })}>Close</Button>
        </Box>
      )
    }
    const labels = v.kind === 'token' ? ['Token / API key'] : ['Username / email', 'Password']
    return (
      <Box flexDirection="column">
        <Text bold>Guardkit | Safe input</Text>
        <Text>Requested for: {v.service}</Text>
        <Text dimColor>Reference: {v.name}. Values go only to the OS keystore.</Text>
        {labels.map((label, i) => (
          <Input key={`f${i}`} label={label} autoFocus={i === 0 ? true : undefined}
            value={DOT.repeat(v.lengths[i] ?? 0)} onInput={t => void edit($, i, t)} onSubmit={() => void submit($, i)} />
        ))}
        {v.message && <Text color="red">{v.message}</Text>}
        <Button key="save" onPress={() => void save($)}>Save</Button>
        <Button key="cancel" onPress={() => void end($, 'cancelled', 'Cancelled. Nothing was stored.')}>Cancel</Button>
      </Box>
    )
  })
}
